import { sql } from "drizzle-orm";
import { check, text, timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";

/** Time-ordered UUIDv7 primary key, generated by Postgres 18. */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

/** URL slug, unique per table. Pair with `slugFormat` in the table's constraints. */
export const slug = () => text().notNull().unique();

/** Lowercase words separated by single hyphens, e.g. `new-delhi`. */
export const slugFormat = (name: string, column: AnyPgColumn) =>
  check(name, sql`${column} ~ '^[a-z0-9]+(-[a-z0-9]+)*$'`);

export const timestamps = {
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date())
};

/** Optional SEO overrides; pages generate defaults when these are empty. */
export const seo = {
  metaTitle: text(),
  metaDescription: text()
};
